import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  FiBookOpen,
  FiImage,
  FiMessageSquare,
  FiPlus,
  FiSettings,
  FiShield,
  FiVideo,
  FiArrowRight,
  FiMail,
  FiTrendingUp,
  FiLayers,
  FiRefreshCw
} from 'react-icons/fi';
import { useNavigate } from 'react-router-dom';

import api from '../../services/api';
import { useLanguage } from '../../contexts/LanguageContext';

const AdminDashboard = () => {
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [dashboardData, setDashboardData] = useState({
    total_admin: 0,
    total_courses: 0,
    total_messages: 0,
    total_gallery: 0,
    total_videos: 0,
    total_schools: 0,
    recent_messages: [],
  });

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [showQuickMenu, setShowQuickMenu] = useState(false);

  const fetchStats = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    try {
      const res = await api.get('/api/admin/dashboard-stats');
      if (res.data) {
        setDashboardData(res.data);
      }
    } catch (err) {
      console.warn('Dashboard stats fallback:', err);
      try {
        const [coursesRes, messagesRes, galleryRes, usersRes, videosRes] = await Promise.allSettled([
          api.get('/api/courses/'),
          api.get('/api/contact/'),
          api.get('/api/gallery/'),
          api.get('/api/admin/users'),
          api.get('/api/videos/'),
        ]);

        const getLen = (r) => (r.status === 'fulfilled' && Array.isArray(r.value.data) ? r.value.data.length : 0);

        setDashboardData({
          total_courses: getLen(coursesRes),
          total_messages: getLen(messagesRes),
          total_gallery: getLen(galleryRes),
          total_admin: getLen(usersRes),
          total_videos: getLen(videosRes),
          total_schools: 1,
          recent_messages: messagesRes.status === 'fulfilled' && Array.isArray(messagesRes.value.data) ? messagesRes.value.data.slice(0, 5) : [],
        });
      } catch (fallbackErr) {
        console.error('Fallback error:', fallbackErr);
      }
    } finally {
      setLastUpdated(new Date());
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  // Top 4 Stat Cards with 100% REAL database numbers
  const topStats = useMemo(() => [
    {
      id: 'courses',
      count: dashboardData.total_courses,
      label: isKhmer ? 'វគ្គសិក្សាទាំងអស់' : 'Total Courses',
      sublabel: 'Available Programs',
      gradient: 'from-[#3B82F6] via-[#2563EB] to-[#1D4ED8]',
      icon: FiBookOpen,
      path: '/courses',
    },
    {
      id: 'messages',
      count: dashboardData.total_messages,
      label: isKhmer ? 'សារទំនាក់ទំនង' : 'Contact Inquiries',
      sublabel: 'Received Inquiries',
      gradient: 'from-[#8B5CF6] via-[#7C3AED] to-[#6D28D9]',
      icon: FiMessageSquare,
      path: '/messages',
    },
    {
      id: 'gallery',
      count: dashboardData.total_gallery,
      label: isKhmer ? 'រូបភាព Gallery' : 'Gallery Photos',
      sublabel: 'Uploaded Photos',
      gradient: 'from-[#06B6D4] via-[#0891B2] to-[#0E7490]',
      icon: FiImage,
      path: '/gallery',
    },
    {
      id: 'admin',
      count: dashboardData.total_admin,
      label: isKhmer ? 'អ្នកគ្រប់គ្រងប្រព័ន្ធ' : 'Admin Accounts',
      sublabel: 'Active Administrators',
      gradient: 'from-[#10B981] via-[#059669] to-[#047857]',
      icon: FiShield,
      path: '/settings',
    },
  ], [dashboardData, isKhmer]);

  // Content breakdown metrics
  const contentMetrics = [
    { label: isKhmer ? 'វគ្គសិក្សា' : 'Courses', value: dashboardData.total_courses, color: 'bg-blue-600' },
    { label: isKhmer ? 'រូបភាព Gallery' : 'Gallery Photos', value: dashboardData.total_gallery, color: 'bg-cyan-500' },
    { label: isKhmer ? 'វីដេអូ' : 'Videos', value: dashboardData.total_videos, color: 'bg-indigo-500' },
    { label: isKhmer ? 'សារទំនាក់ទំនង' : 'Messages', value: dashboardData.total_messages, color: 'bg-purple-500' },
    { label: isKhmer ? 'អ្នកគ្រប់គ្រង' : 'Admin Users', value: dashboardData.total_admin, color: 'bg-emerald-500' },
  ];

  const totalContent = contentMetrics.reduce((sum, item) => sum + item.value, 0);
  const highestMetric = Math.max(...contentMetrics.map((item) => item.value), 1);

  // SVG Donut Calculations for Real Content Distribution
  const radius = 64;
  const circumference = 2 * Math.PI * radius;

  // Calculate course vs other ratio for the visual donut
  const primaryCount = dashboardData.total_courses;
  const otherCount = Math.max(totalContent - primaryCount, 0);
  const primaryStroke = totalContent > 0 ? (primaryCount / totalContent) * circumference : 0;
  const otherStroke = totalContent > 0 ? (otherCount / totalContent) * circumference : 0;

  if (loading) {
    return (
      <div className="flex min-h-[70vh] items-center justify-center bg-[#f8fafc]">
        <div className="text-center">
          <div className="mx-auto h-12 w-12 animate-spin rounded-full border-4 border-blue-200 border-t-[#2563EB]" />
          <p className="mt-4 text-sm font-semibold text-slate-600">
            {isKhmer ? 'កំពុងផ្ទុកទិន្នន័យ Dashboard...' : 'Loading Dashboard statistics...'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <main className={`min-h-screen bg-[#F4F7FB] p-4 md:p-6 lg:p-8 space-y-6 ${isKhmer ? 'font-khmer' : ''}`}>

      {/* =====================================================
          1. TOP WELCOME BANNER
      ===================================================== */}
      <section className="relative overflow-hidden rounded-[28px] bg-gradient-to-r from-[#3B82F6] via-[#6366F1] to-[#8B5CF6] p-6 sm:p-8 text-white shadow-xl shadow-indigo-500/10">
        <div className="absolute -right-12 -top-16 h-64 w-64 rounded-full bg-white/10 blur-2xl pointer-events-none" />
        <div className="absolute right-32 -bottom-20 h-56 w-56 rounded-full bg-purple-400/20 blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6">
          <div>
            <h1 className="text-2xl sm:text-3xl lg:text-4xl font-extrabold tracking-tight flex items-center gap-2">
              Welcome back, Admin <span className="inline-block animate-bounce">👋</span>
            </h1>
            <p className="mt-2 text-xs sm:text-sm text-indigo-100 font-medium max-w-xl leading-relaxed">
              {isKhmer
                ? 'តាមដាន និងគ្រប់គ្រងទិន្នន័យវគ្គសិក្សា រូបភាព និងសារទំនាក់ទំនងជាក់ស្តែង។'
                : 'Track and manage your real-time school programs, gallery, and contact inquiries.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => fetchStats(true)}
              disabled={refreshing}
              className="inline-flex items-center gap-2 px-4 py-3 rounded-full bg-white/15 hover:bg-white/25 text-white font-bold text-xs sm:text-sm backdrop-blur transition-all"
            >
              <FiRefreshCw className={refreshing ? 'animate-spin' : ''} />
              <span>{isKhmer ? 'ផ្ទុកទិន្នន័យឡើងវិញ' : 'Refresh'}</span>
            </button>

            <div className="relative">
              <button
                type="button"
                onClick={() => setShowQuickMenu(!showQuickMenu)}
                className="inline-flex items-center gap-2 px-6 py-3 rounded-full bg-[#00D2FF] hover:bg-[#00c0eb] text-white font-bold text-xs sm:text-sm shadow-lg shadow-cyan-500/30 transition-all transform hover:scale-105 active:scale-95"
              >
                <FiPlus size={16} className="stroke-[3]" />
                <span>Quick Action</span>
              </button>

              {/* Quick Action Dropdown */}
              {showQuickMenu && (
                <div className="absolute right-0 mt-3 w-56 rounded-2xl bg-white p-2 shadow-2xl border border-slate-100 z-50 animate-fade-in text-slate-800">
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/courses'); }}
                    className="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-50 hover:text-blue-600 transition-colors text-left"
                  >
                    <FiBookOpen className="text-blue-600" />
                    <span>{isKhmer ? 'គ្រប់គ្រងវគ្គសិក្សា' : 'Manage Courses'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/gallery'); }}
                    className="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-50 hover:text-cyan-600 transition-colors text-left"
                  >
                    <FiImage className="text-cyan-600" />
                    <span>{isKhmer ? 'រូបភាព Gallery' : 'Upload Gallery'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/messages'); }}
                    className="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-50 hover:text-rose-600 transition-colors text-left"
                  >
                    <FiMessageSquare className="text-rose-600" />
                    <span>{isKhmer ? 'សារទំនាក់ទំនង' : 'View Messages'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/settings'); }}
                    className="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-50 hover:text-indigo-600 transition-colors text-left"
                  >
                    <FiSettings className="text-indigo-600" />
                    <span>{isKhmer ? 'ការកំណត់ប្រព័ន្ធ' : 'Admin Settings'}</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* =====================================================
          2. TOP 4 STAT CARDS (100% REAL DATA)
      ===================================================== */}
      <section className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
        {topStats.map((stat) => {
          const Icon = stat.icon;
          return (
            <div
              key={stat.id}
              onClick={() => navigate(stat.path)}
              className={`relative overflow-hidden rounded-3xl bg-gradient-to-br ${stat.gradient} p-6 text-white shadow-lg cursor-pointer transition-all duration-300 hover:-translate-y-1.5 hover:shadow-2xl group`}
            >
              {/* Top-Right Decorative Circle Bubble */}
              <div className="absolute -right-6 -top-6 w-28 h-28 rounded-full bg-white/15 pointer-events-none transition-transform group-hover:scale-125 duration-500" />

              {/* Top-Left Translucent Icon Box */}
              <div className="relative z-10 w-11 h-11 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center shadow-inner">
                <Icon size={20} className="text-white" />
              </div>

              {/* Stat Value & Label */}
              <div className="relative z-10 mt-6">
                <h3 className="text-3xl sm:text-4xl font-extrabold tracking-tight tabular-nums drop-shadow-sm">
                  {stat.count}
                </h3>
                <p className="mt-1 text-xs sm:text-sm font-semibold text-white/90 drop-shadow-sm">
                  {stat.label}
                </p>
              </div>
            </div>
          );
        })}
      </section>

      {/* =====================================================
          3. REAL CONTENT ANALYTICS & DISTRIBUTION
      ===================================================== */}
      <section className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* LEFT: CONTENT VOLUME & BREAKDOWN (8 cols) */}
        <div className="lg:col-span-8 bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/80 shadow-sm flex flex-col justify-between">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-base sm:text-lg font-extrabold text-slate-900">
                {isKhmer ? 'ការបែងចែកមាតិកាប្រព័ន្ធ' : 'Content & Records Analytics'}
              </h2>
              <p className="text-xs text-slate-500 font-medium mt-0.5">
                {isKhmer ? 'ទិន្នន័យជាក់ស្តែងនៃមាតិកាដែលកំពុងដំណើរការក្នុងប្រព័ន្ធ។' : 'Real-time volume of records currently active in the database.'}
              </p>
            </div>
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-emerald-50 text-emerald-700 text-xs font-bold">
              <FiTrendingUp size={14} /> Live Data
            </span>
          </div>

          {/* Progress Bars */}
          <div className="mt-6 space-y-4">
            {contentMetrics.map((metric) => (
              <div key={metric.label}>
                <div className="mb-1.5 flex items-center justify-between text-xs font-semibold">
                  <span className="text-slate-700">{metric.label}</span>
                  <span className="text-slate-900 font-bold tabular-nums">{metric.value}</span>
                </div>
                <div className="h-2.5 w-full rounded-full bg-slate-100 overflow-hidden">
                  <div
                    className={`h-full rounded-full ${metric.color} transition-all duration-700`}
                    style={{ width: `${metric.value ? Math.max((metric.value / highestMetric) * 100, 6) : 0}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-between text-xs text-slate-400 font-medium">
            <span>{isKhmer ? 'ធ្វើបច្ចុប្បន្នភាពចុងក្រោយ' : 'Last refreshed'}: {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            <span className="text-[#2563EB] font-bold">{isKhmer ? 'ទិន្នន័យសរុប' : 'Total Items'}: {totalContent}</span>
          </div>
        </div>

        {/* RIGHT: SYSTEM CONTENT PROPORTION (4 cols) */}
        <div className="lg:col-span-4 bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/80 shadow-sm flex flex-col justify-between">
          <div>
            <h2 className="text-base sm:text-lg font-extrabold text-slate-900">
              {isKhmer ? 'ផលធៀបមាតិកា' : 'Content Proportion'}
            </h2>
            <p className="text-xs text-slate-500 font-medium mt-0.5">
              {isKhmer ? 'ផលធៀបវគ្គសិក្សា និងមាតិកាផ្សេងៗ' : 'Courses vs Media Distribution'}
            </p>
          </div>

          {/* SVG Donut Chart */}
          <div className="my-6 flex flex-col items-center justify-center">
            <div className="relative w-44 h-44 flex items-center justify-center">
              <svg className="w-full h-full -rotate-90" viewBox="0 0 160 160">
                {/* Background Ring */}
                <circle
                  cx="80"
                  cy="80"
                  r={radius}
                  fill="transparent"
                  stroke="#E2E8F0"
                  strokeWidth="22"
                />
                {/* Primary Courses Arc (Blue) */}
                {totalContent > 0 && (
                  <circle
                    cx="80"
                    cy="80"
                    r={radius}
                    fill="transparent"
                    stroke="#3B82F6"
                    strokeWidth="22"
                    strokeDasharray={`${primaryStroke} ${circumference}`}
                    strokeDashoffset="0"
                    className="transition-all duration-700"
                  />
                )}
                {/* Other Media Arc (Purple) */}
                {totalContent > 0 && (
                  <circle
                    cx="80"
                    cy="80"
                    r={radius}
                    fill="transparent"
                    stroke="#8B5CF6"
                    strokeWidth="22"
                    strokeDasharray={`${otherStroke} ${circumference}`}
                    strokeDashoffset={-primaryStroke}
                    className="transition-all duration-700"
                  />
                )}
              </svg>

              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-2xl font-black text-slate-900">{totalContent}</span>
                <span className="text-[10px] uppercase font-bold text-slate-400">Total</span>
              </div>
            </div>

            {/* Inline Legend */}
            <div className="flex items-center gap-6 mt-3">
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded-sm bg-[#3B82F6]" />
                <span className="text-xs font-semibold text-slate-600">{isKhmer ? 'វគ្គសិក្សា' : 'Courses'}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded-sm bg-[#8B5CF6]" />
                <span className="text-xs font-semibold text-slate-600">{isKhmer ? 'មាតិកាផ្សេងៗ' : 'Media/Other'}</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 border-t border-slate-100 pt-4 text-center">
            <div>
              <p className="text-base font-extrabold text-slate-900">{dashboardData.total_courses}</p>
              <p className="text-xs font-semibold text-slate-400">{isKhmer ? 'វគ្គសិក្សា' : 'Courses'}</p>
            </div>
            <div>
              <p className="text-base font-extrabold text-slate-900">{otherCount}</p>
              <p className="text-xs font-semibold text-slate-400">{isKhmer ? 'មាតិកាផ្សេងៗ' : 'Other'}</p>
            </div>
          </div>
        </div>
      </section>

      {/* =====================================================
          4. RECENT INQUIRIES & MESSAGES (100% REAL DATA)
      ===================================================== */}
      <section className="bg-white rounded-3xl p-6 sm:p-8 border border-slate-200/80 shadow-sm">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-base sm:text-lg font-extrabold text-slate-900">
              {isKhmer ? 'សារទំនាក់ទំនងថ្មីៗ (Recent Inquiries)' : 'Recent Inquiries & Messages'}
            </h2>
            <p className="text-xs text-slate-500 font-medium mt-0.5">
              {isKhmer ? 'សារ និងសំណួរដែលបានផ្ញើចេញពីទំព័រ Contact' : 'Direct messages submitted by website visitors.'}
            </p>
          </div>

          <button
            type="button"
            onClick={() => navigate('/messages')}
            className="inline-flex items-center gap-1.5 text-xs font-bold text-[#2563EB] hover:text-blue-700 transition-colors"
          >
            <span>{isKhmer ? 'មើលសារទាំងអស់' : 'View All Messages'}</span>
            <FiArrowRight size={14} />
          </button>
        </div>

        {dashboardData.recent_messages && dashboardData.recent_messages.length > 0 ? (
          <div className="divide-y divide-slate-100">
            {dashboardData.recent_messages.map((msg, index) => (
              <div key={msg.id || index} className="py-3.5 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-slate-50/70 px-3 rounded-2xl transition-colors">
                <div className="flex items-start gap-3 min-w-0">
                  <div className="w-9 h-9 rounded-xl bg-blue-50 text-[#2563EB] flex items-center justify-center flex-shrink-0 mt-0.5">
                    <FiMail size={16} />
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="text-xs sm:text-sm font-bold text-slate-900 truncate">{msg.name || 'Anonymous'}</p>
                      {msg.email && <span className="text-xs text-slate-400 truncate">({msg.email})</span>}
                    </div>
                    <p className="text-xs text-slate-600 line-clamp-1 mt-0.5">{msg.subject || msg.message || 'No subject'}</p>
                  </div>
                </div>

                {msg.created_at && (
                  <span className="text-[11px] font-semibold text-slate-400 flex-shrink-0">
                    {msg.created_at}
                  </span>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-10 border border-dashed border-slate-200 rounded-2xl">
            <FiMessageSquare size={28} className="mx-auto text-slate-300 mb-2" />
            <p className="text-xs font-bold text-slate-600">{isKhmer ? 'មិនទាន់មានសារទំនាក់ទំនងថ្មីទេ' : 'No contact messages yet'}</p>
            <p className="text-[11px] text-slate-400 mt-1">{isKhmer ? 'សារដែលភ្ញៀវផ្ញើមកនឹងបង្ហាញនៅទីនេះ' : 'Messages submitted on the contact page will appear here.'}</p>
          </div>
        )}
      </section>

    </main>
  );
};

export default AdminDashboard;
